package com.mercato.session;
import com.mercato.Auth.*;import com.mercato.Entity.*;import com.mercato.Repository.UserRepository;import com.mercato.Security.jwt.JwtUtils;import com.mercato.Service.CartService;import com.mercato.Session.*;
import org.junit.jupiter.api.*;import org.springframework.mock.web.MockHttpServletRequest;
import java.time.Instant;import java.util.*;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class MfaLifecycleTest {
 UserRepository users;MfaCredentialRepository repository;SessionService sessions;MfaService mfa;EcommUser user;MfaCredential credential;SeedCipher cipher;MockHttpServletRequest request;org.springframework.transaction.PlatformTransactionManager transactions;SessionRevocation revocation;com.mercato.Repository.AccountAccessEventRepository audit;
 @BeforeEach void fixture(){users=mock(UserRepository.class);repository=mock(MfaCredentialRepository.class);sessions=new SessionService(users,mock(JwtUtils.class));cipher=new SeedCipher("AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=");transactions=mock(org.springframework.transaction.PlatformTransactionManager.class);revocation=mock(SessionRevocation.class);audit=mock(com.mercato.Repository.AccountAccessEventRepository.class);mfa=new MfaService(repository,users,cipher,sessions,mock(CartService.class),transactions,revocation,audit);user=new EcommUser();user.setUserId("ADMIN-1");user.setUsername("admin");user.setEnabled(true);user.setEmailVerified(true);user.setRoles(Set.of(new Role(AppRole.ROLE_ADMIN)));when(users.findByUserIdForUpdate("ADMIN-1")).thenReturn(Optional.of(user));when(users.findByUserId("ADMIN-1")).thenReturn(Optional.of(user));credential=new MfaCredential();credential.setUserId("ADMIN-1");credential.setEncryptedSeed(cipher.encrypt("ADMIN-1","GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ"));when(repository.findById("ADMIN-1")).thenReturn(Optional.of(credential));request=new MockHttpServletRequest();sessions.establish(request,user,"CHALLENGE_REQUIRED");}
 @Test void abandonedReplacementDoesNotBlockAnotherSessionsEstablishedAuthenticator(){credential.setPendingSeed(cipher.encrypt("ADMIN-1",Totp.secret()));credential.setPendingExpiresAt(Instant.now().minusSeconds(60));var result=mfa.verify(request,Totp.code("GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ",Instant.now().getEpochSecond()/30),false);assertEquals(true,result.get("authenticated"));}
 @Test void usedRecoveryCodeCannotBeReplayedButPermitsRecentReplacement(){credential.getRecoveryHashes().add(AuthHash.digest("ADMIN-1:RECOVERY"));mfa.verify(request,"RECOVERY",true);assertThrows(AuthProofException.class,()->mfa.verify(request,"RECOVERY",true));var enrollment=mfa.enroll(request,null,true);assertNotNull(enrollment.get("secret"));}
 @Test void failedProofCommitNeverElevatesTheCookieSession(){credential.getRecoveryHashes().add(AuthHash.digest("ADMIN-1:RECOVERY"));doThrow(new org.springframework.dao.DataAccessResourceFailureException("commit unavailable")).when(transactions).commit(org.mockito.ArgumentMatchers.nullable(org.springframework.transaction.TransactionStatus.class));assertThrows(org.springframework.dao.DataAccessResourceFailureException.class,()->mfa.verify(request,"RECOVERY",true));assertEquals("CHALLENGE_REQUIRED",sessions.identity(request).mfaState());}
 @Test void operatorRecoveryRequiresAnotherRecentlyVerifiedAdministratorAndAuditsTheRevocation(){
  assertThrows(org.springframework.security.access.AccessDeniedException.class,()->mfa.operatorRecovery(request,"ADMIN-2","Operator confirmed ownership out of band",0L));
  sessions.completeMfa(request);
  assertThrows(org.springframework.security.access.AccessDeniedException.class,()->mfa.operatorRecovery(request,"ADMIN-1","Operator confirmed ownership out of band",0L));
  var target=new EcommUser();target.setUserId("ADMIN-2");target.setRoles(Set.of(new Role(AppRole.ROLE_ADMIN)));when(users.findByUserIdForUpdate("ADMIN-2")).thenReturn(Optional.of(target));var seed=new MfaCredential();seed.setUserId("ADMIN-2");when(repository.findById("ADMIN-2")).thenReturn(Optional.of(seed));
  mfa.operatorRecovery(request,"ADMIN-2","Operator confirmed ownership out of band",0L);
  assertEquals(1,target.getAccessVersion());verify(revocation).revokeAll("ADMIN-2");var event=org.mockito.ArgumentCaptor.forClass(AccountAccessEvent.class);verify(audit).save(event.capture());assertEquals("MFA_OPERATOR_RECOVERY",event.getValue().getAction());
 }
}
